"""Seal -> qualify -> consensus -> seal -> unblind; no human results generated by build."""

import argparse
import json
import shutil
from collections import Counter
from datetime import UTC, datetime
from itertools import combinations
from pathlib import Path

from .common import PACKAGE, digest, file_hash, read_json, write_json
from .native_listener_validation import CHOICES, OUT, RULES, VERSION, require


def verify_package(package):
    seal = read_json(package / "preregistration-seal.json")
    require(
        file_hash(package / "preregistration.json") == seal["sha256"], "preregistration changed"
    )
    for name, sha in seal["files"].items():
        require(file_hash(package / name) == sha, "package changed: " + name)
    plan = read_json(package / "preregistration.json")
    require(plan["rules"] == RULES, "rules differ from preregistration")
    require(file_hash(Path(__file__)) == plan["analysis_sha256"], "analysis code changed")
    require(
        file_hash(PACKAGE / "perceptual_tone/native_listener_validation.py")
        == plan["implementation_sha256"],
        "builder code changed",
    )
    require(
        file_hash(PACKAGE / "native-listener-validation-protocol.md") == plan["protocol_sha256"],
        "protocol changed",
    )
    require(
        digest(read_json(package / "response-schema.json")) == plan["schema_sha256"],
        "schema changed",
    )
    return read_json(package / "PRIVATE/trial-key.json")


def seal_responses(package, incoming, destination, collection_closed=False):
    require(collection_closed, "explicit collection closure required before response seal")
    key = verify_package(package)
    require(not destination.exists(), "response destination already exists")
    paths = sorted(incoming.glob("*.json"))
    require(paths, "no raw submissions; cannot seal absent responses")
    seen = set()
    records = []
    # Preserve complete AND incomplete submissions; qualification does validation later.
    for path in paths:
        data = read_json(path)
        lid = data.get("listener_id")
        require(lid in key["listeners"] and lid not in seen, "unknown or duplicate listener")
        require(data.get("packet_sha256") == key["listeners"][lid]["packet_sha256"], "wrong packet")
        seen.add(lid)
        records.append((lid, path))
    destination.mkdir(parents=True)
    files = {}
    for lid, path in records:
        target = destination / "raw" / (lid + ".json")
        target.parent.mkdir(exist_ok=True)
        shutil.copyfile(path, target)
        files[str(target.relative_to(destination))] = file_hash(target)
    write_json(
        destination / "response-seal.json",
        {
            "version": VERSION,
            "sealed_at": datetime.now(UTC).isoformat(),
            "collection_closed": True,
            "package_seal_sha256": file_hash(package / "preregistration-seal.json"),
            "files": files,
            "absent_listeners": sorted(set(key["listeners"]) - seen),
            "note": "Raw bytes archived before reliability scoring; no model comparison yet.",
        },
    )


def sealed_raw(package, responses):
    key = verify_package(package)
    require((responses / "response-seal.json").exists(), "raw response seal required")
    seal = read_json(responses / "response-seal.json")
    require(seal["collection_closed"] and seal["files"], "collection not closed or empty")
    require(
        file_hash(package / "preregistration-seal.json") == seal["package_seal_sha256"],
        "wrong package seal",
    )
    require(
        set(p.relative_to(responses).as_posix() for p in (responses / "raw").glob("*"))
        == set(seal["files"]),
        "raw archive file set changed",
    )
    rows = []
    for name, sha in seal["files"].items():
        require(file_hash(responses / name) == sha, "sealed human response changed")
        rows.append(read_json(responses / name))
    require(len({r["listener_id"] for r in rows}) == len(rows), "duplicate listener")
    return key, rows


def timestamp(value):
    require(isinstance(value, str), "missing timestamp")
    dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    require(dt.tzinfo is not None, "timezone required")
    return dt


def validate_response(data, listener):
    require(
        set(data)
        == {
            "version",
            "listener_id",
            "packet_sha256",
            "eligibility",
            "background",
            "started_at",
            "completed_at",
            "responses",
        },
        "response fields",
    )
    require(
        data["version"] == VERSION and data["packet_sha256"] == listener["packet_sha256"],
        "response version",
    )
    require(
        set(data["eligibility"]) == {"adult", "native", "primary_childhood", "independent"}
        and all(v is True for v in data["eligibility"].values()),
        "eligibility not attested",
    )
    require(
        set(data["background"]) == {"region", "other_variety", "current_language"}
        and all(isinstance(v, str) and len(v) <= 200 for v in data["background"].values()),
        "background schema",
    )
    require(len(data["responses"]) == 68, "incomplete response set")
    last = timestamp(data["started_at"])
    for r, t in zip(data["responses"], listener["trials"], strict=True):
        require(
            set(r) == {"trial_id", "position", "answer", "answered_at", "play_count"},
            "trial response fields",
        )
        require(
            r["trial_id"] == t["trial_id"] and r["position"] == t["position"],
            "trial identity/order",
        )
        require(r["answer"] in CHOICES, "invalid categorical response")
        require(
            type(r["play_count"]) is int and r["play_count"] >= 1, "no complete playback recorded"
        )
        now = timestamp(r["answered_at"])
        require(now >= last, "timestamp order")
        last = now
    require(timestamp(data["completed_at"]) >= last, "completion timestamp")


def score_listener(data, listener, items):
    try:
        validate_response(data, listener)
    except (ValueError, KeyError, TypeError) as error:
        return {
            "qualified": False,
            "reason": str(error),
            "native_correct": None,
            "repeat_consistent": None,
        }, {}
    answers = {}
    for r, t in zip(data["responses"], listener["trials"], strict=True):
        answers[(t["item_id"], t["view"], t["repeat"])] = r["answer"]
    correct = Counter()
    for item in items:
        if item["kind"] == "native_positive":
            correct[item["native_label"]] += (
                answers[item["id"], "context", False] == item["native_label"]
            )
    repeats = [t for t in listener["trials"] if t["repeat"]]
    consistency = sum(
        answers[t["item_id"], t["view"], True] == answers[t["item_id"], t["view"], False]
        for t in repeats
    )
    qualified = (
        sum(correct.values()) >= RULES["native_correct_min"]
        and all(correct[t] >= RULES["native_per_tone_min"] for t in CHOICES[:4])
        and consistency >= RULES["repeat_consistent_min"]
    )
    challenge = [i for i in items if i["kind"] == "native_challenge"]
    return {
        "qualified": qualified,
        "reason": "fixed reliability gates",
        "native_correct": sum(correct.values()),
        "native_denominator": 12,
        "native_per_tone": dict(correct),
        "repeat_consistent": consistency,
        "repeat_denominator": 8,
        "challenge_correct_descriptive": sum(
            answers[i["id"], "context", False] == i["native_label"] for i in challenge
        ),
        "challenge_denominator": len(challenge),
        "repeat_by_kind": {
            kind: {
                "consistent": sum(
                    answers[t["item_id"], t["view"], True]
                    == answers[t["item_id"], t["view"], False]
                    for t in repeats
                    if t["kind"] == kind
                ),
                "total": sum(t["kind"] == kind for t in repeats),
            }
            for kind in sorted({t["kind"] for t in repeats})
        },
    }, answers


def case_evidence(item_id, qualified_answers):
    n = len(qualified_answers)
    paired, counts, repeat_conflicts = [], {"crop": Counter(), "context": Counter()}, 0
    for answers in qualified_answers:
        crop, context = answers[item_id, "crop", False], answers[item_id, "context", False]
        repeat = answers.get((item_id, "context", True))
        conflict = repeat is not None and repeat != context
        repeat_conflicts += conflict
        # Keep unreliable local judgments in denominator as UNCLEAR; never cherry-pick raters.
        if conflict:
            crop = context = "UNCLEAR"
        counts["crop"][crop] += 1
        counts["context"][context] += 1
        paired.append(crop if crop == context and crop != "UNCLEAR" else None)
    votes = Counter(p for p in paired if p is not None)
    winner, support = votes.most_common(1)[0] if votes else (None, 0)
    unclear = max(counts[v]["UNCLEAR"] for v in counts) / n if n else 1
    state, tone = "UNRESOLVED", None
    if n >= RULES["minimum_qualified"]:
        if (
            n >= RULES["strong_n_min"]
            and support / n >= RULES["strong_joint_fraction"]
            and unclear <= RULES["strong_unclear_max"]
        ):
            state, tone = "STRONG", winner
        elif (
            support / n >= RULES["moderate_joint_fraction"]
            and unclear <= RULES["moderate_unclear_max"]
        ):
            state, tone = "MODERATE", winner
        elif all(n - counts[v]["UNCLEAR"] >= 2 for v in counts):
            state = "AMBIGUOUS"
    return {
        "id": item_id,
        "state": state,
        "consensus_tone": tone,
        "qualified_n": n,
        "joint_support": support,
        "joint_fraction": support / n if n else None,
        "counts": {v: dict(c) for v, c in counts.items()},
        "local_repeat_conflicts": repeat_conflicts,
        "paired_view_agreement": sum(p is not None for p in paired) / n if n else None,
    }


def inter_rater(items, qualified):
    """Six-category Fleiss kappa; repeats never count as independent raters."""
    report = []
    n = len(qualified)
    for kind in ("disagreement", "agreement", "native_positive", "native_challenge"):
        for view in ("crop", "context"):
            subset = [i for i in items if i["kind"] == kind]
            totals, exact, pairs, valid_exact, valid_pairs = Counter(), 0, 0, 0, 0
            for item in subset:
                labels = [a[item["id"], view, False] for a in qualified]
                totals.update(labels)
                for a, b in combinations(labels, 2):
                    exact += a == b
                    pairs += 1
                    if a != "UNCLEAR" and b != "UNCLEAR":
                        valid_pairs += 1
                        valid_exact += a == b
            po = exact / pairs if pairs else None
            total = sum(totals.values())
            pe = sum((c / total) ** 2 for c in totals.values()) if total else None
            report.append(
                {
                    "kind": kind,
                    "view": view,
                    "items": len(subset),
                    "qualified_n": n,
                    "pairwise_exact_including_unclear": po,
                    "pairwise_exact_excluding_unclear_pairs": valid_exact / valid_pairs
                    if valid_pairs
                    else None,
                    "unclear_fraction": totals["UNCLEAR"] / total if total else None,
                    "pair_denominator": pairs,
                    "non_unclear_pair_denominator": valid_pairs,
                    "fleiss_kappa_six_categories": (po - pe) / (1 - pe)
                    if po is not None and pe < 1
                    else None,
                    "category_counts": dict(totals),
                }
            )
    return report


def analyze_data(key, rows):
    qualification, qualified, valid_submissions = {}, [], []
    for data in rows:
        lid = data["listener_id"]
        score, answers = score_listener(data, key["listeners"][lid], key["items"])
        qualification[lid] = score
        if answers:
            valid_submissions.append(answers)
        if score["qualified"]:
            qualified.append(answers)
    return {
        "qualification": qualification,
        "qualified_n": len(qualified),
        "minimum_met": len(qualified) >= RULES["minimum_qualified"],
        "cases": [
            case_evidence(i["id"], qualified)
            for i in key["items"]
            if i["kind"] in ("disagreement", "agreement")
        ],
        "inter_rater": inter_rater(key["items"], qualified),
        "native_item_confusion": [
            {
                "id": i["id"],
                "kind": i["kind"],
                "native_label": i["native_label"],
                "view": view,
                "all_valid_submission_counts": dict(
                    Counter(a[i["id"], view, False] for a in valid_submissions)
                ),
                "qualified_response_counts": dict(
                    Counter(a[i["id"], view, False] for a in qualified)
                ),
            }
            for i in key["items"]
            if i["kind"].startswith("native")
            for view in ("crop", "context")
        ],
        "note": "Perceptual evidence only. No classifier outputs read.",
    }


def analyze(package, responses):
    key, rows = sealed_raw(package, responses)
    output = analyze_data(key, rows)
    write_json(responses / "perceptual-consensus.json", output)
    write_json(
        responses / "consensus-seal.json",
        {
            "sha256": file_hash(responses / "perceptual-consensus.json"),
            "response_seal_sha256": file_hash(responses / "response-seal.json"),
            "sealed_at": datetime.now(UTC).isoformat(),
        },
    )
    return output


def unblind(package, responses):
    key, rows = sealed_raw(package, responses)
    require((responses / "consensus-seal.json").exists(), "sealed perceptual consensus required")
    seal = read_json(responses / "consensus-seal.json")
    require(
        file_hash(responses / "response-seal.json") == seal["response_seal_sha256"],
        "response seal changed",
    )
    require(
        file_hash(responses / "perceptual-consensus.json") == seal["sha256"], "consensus changed"
    )
    consensus = read_json(responses / "perceptual-consensus.json")
    require(consensus == analyze_data(key, rows), "consensus must reproduce from sealed responses")
    # First and only prediction-file read in this module occurs AFTER all gates above.
    reference = read_json(package / "PRIVATE/prediction-reference.json")
    require(file_hash(reference["path"]) == reference["sha256"], "frozen predictions changed")
    predictions = {
        (r["id"], r["head"]): r["prediction"]
        for r in read_json(reference["path"])["rows"]
        if r["arm"] == "ACOUSTIC_WEIGHTED" and r["perturbation"] == "BASE"
    }
    ids = {i["id"] for i in key["items"] if i["kind"] == "disagreement"}
    result = []
    for case in consensus["cases"]:
        if case["id"] not in ids:
            continue
        row = {k: case[k] for k in ("id", "state", "consensus_tone", "qualified_n")}
        for head in ("expanded", "pilot"):
            prediction = predictions[case["id"], head]
            row[head + "_prediction"] = prediction
            row[head + "_match"] = (
                prediction == case["consensus_tone"]
                if case["state"] in ("STRONG", "MODERATE")
                else None
            )
        result.append(row)
    write_json(
        responses / "unblinded-comparison.json",
        {
            "cases": result,
            "consensus_seal_sha256": file_hash(responses / "consensus-seal.json"),
            "note": "No automatic head selection, refit, training, or integration authorization.",
        },
    )
    return result


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["seal", "analyze", "unblind"])
    parser.add_argument("--package", type=Path, default=OUT)
    parser.add_argument("--responses", type=Path, required=True)
    parser.add_argument("--incoming", type=Path)
    parser.add_argument("--collection-closed", action="store_true")
    args = parser.parse_args()
    if args.command == "seal":
        require(args.incoming is not None, "--incoming required")
        seal_responses(args.package, args.incoming, args.responses, args.collection_closed)
    elif args.command == "analyze":
        print(json.dumps(analyze(args.package, args.responses), indent=2))
    else:
        print(json.dumps(unblind(args.package, args.responses), indent=2))
